/**
 * On-chain tests: proofs generated by the SDK are verified by the real Microchain contracts
 * (generated HonkVerifiers, ERC-8039 adapters, ZK signer factory, Nexus validator) on a local Anvil
 * chain. Skipped when Foundry's `anvil` is not installed.
 */

import { createBarretenberg } from "../../src/internal/prover.js";
import { Barretenberg } from "@aztec/bb.js";
import { encodeFunctionData, getAddress, parseAbi, toHex, type Address, type Hex } from "viem";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import {
    ERC1271_MAGIC_VALUE,
    computeZKSignerAddress,
    createZKSigner,
    encodeSafeSignatures,
    encodeZKSignerSignature,
    getZKSignerConfiguration,
    isValidZKSignature,
    zkMultiSigEcdsaSignerAbi,
} from "../../src/zk-multisig/safe.js";
import {
    DEFAULT_GAS,
    encodeValidatorInitData,
    encodeUpdateStateRootCall,
    generateNexusUserOperationProof,
    getNexusAccountStatus,
    getNexusUserOperationHash,
    getValidatorStateRoot,
    prepareNexusUserOperation,
    zkMultiSigValidatorAbi,
} from "../../src/zk-multisig/nexus.js";
import {
    createMultiSigState,
    encodeMultiSigPublicInputs,
    encodeStateValidationPublicInputs,
    generateMultiSigProof,
    generateStateValidationProof,
    type MultiSigConfig,
} from "../../src/zk-multisig/index.js";
import { toPackedUserOperation } from "viem/account-abstraction";
import { loadCircuit, testAccounts } from "../helpers.js";
import { anvilAvailable, deployAll, loadContract, startChain, type Chain, type Deployment } from "./harness.js";

const PROOF_MAGIC_VALUE = "0x534f5876";
const txCircuit = loadCircuit("zk_multi_sig_ecdsa");
const stateCircuit = loadCircuit("zk_multi_sig_ecdsa_private_state_validation");
const SALT = 0x0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdefn;
const TIMEOUT = 300_000;

const adapterAbi = parseAbi(["function verifyProof(bytes publicInputs, bytes proof) view returns (bytes4)"]);

describe.skipIf(!anvilAvailable())("on-chain (Anvil)", () => {
    let chain: Chain;
    let contracts: Deployment;
    let api: Barretenberg;

    const accounts = testAccounts(3, "onchain");
    const config: MultiSigConfig = { signers: accounts.map((a) => a.address), threshold: 2, salt: SALT };
    const state = createMultiSigState(config);
    let stateProof: Hex;

    beforeAll(async () => {
        chain = await startChain();
        api = (await createBarretenberg()) as Barretenberg;
        contracts = await deployAll(chain);
        stateProof = (await generateStateValidationProof(config, stateCircuit, { barretenberg: api })).proof;
    }, TIMEOUT);

    afterAll(async () => {
        await api.destroy();
        await chain.stop();
    });

    const verify = (adapter: Address, publicInputs: Hex, proof: Hex) =>
        chain.publicClient.readContract({
            address: adapter,
            abi: adapterAbi,
            functionName: "verifyProof",
            args: [publicInputs, proof],
        });

    describe("ERC-8039 verifier adapters", () => {
        it("accept the SDK's state-validation proof, and only for its state root", async () => {
            expect(
                await verify(contracts.stateAdapter, encodeStateValidationPublicInputs(state.stateRoot), stateProof),
            ).toBe(PROOF_MAGIC_VALUE);
            expect(
                await verify(
                    contracts.stateAdapter,
                    encodeStateValidationPublicInputs(state.stateRoot + 1n),
                    stateProof,
                ),
            ).toBe("0x00000000");
        });

        it("reject a tampered proof without reverting", async () => {
            const bytes = stateProof.slice(2).split("");
            bytes[200] = bytes[200] === "a" ? "b" : "a";
            expect(
                await verify(
                    contracts.stateAdapter,
                    encodeStateValidationPublicInputs(state.stateRoot),
                    `0x${bytes.join("")}`,
                ),
            ).toBe("0x00000000");
        });

        it(
            "accept the SDK's transaction proof, and only for its hash and state root",
            async () => {
                const hash = toHex("on-chain transfer", { size: 32 });
                const signatures = await Promise.all([0, 2].map((i) => accounts[i].sign({ hash })));
                const { proof } = await generateMultiSigProof(config, hash, signatures, state.stateRoot, txCircuit, {
                    barretenberg: api,
                });

                expect(
                    await verify(contracts.txAdapter, encodeMultiSigPublicInputs(hash, state.stateRoot), proof),
                ).toBe(PROOF_MAGIC_VALUE);
                expect(
                    await verify(
                        contracts.txAdapter,
                        encodeMultiSigPublicInputs(toHex("other", { size: 32 }), state.stateRoot),
                        proof,
                    ),
                ).toBe("0x00000000");
                expect(
                    await verify(contracts.txAdapter, encodeMultiSigPublicInputs(hash, state.stateRoot + 1n), proof),
                ).toBe("0x00000000");
            },
            TIMEOUT,
        );
    });

    describe("Safe: ZK signer", () => {
        const hash = toHex("safe transaction hash", { size: 32 });
        let proof: Hex;
        let signer: Address;

        it("creates the ZK signer at the predicted address, idempotently", async () => {
            const predicted = await computeZKSignerAddress(chain.publicClient, {
                factory: contracts.safeFactory,
                stateRoot: state.stateRoot,
                verifier: contracts.txAdapter,
            });
            expect(await chain.publicClient.getCode({ address: predicted })).toBeUndefined();

            const created = await createZKSigner(chain.walletClient, {
                factory: contracts.safeFactory,
                stateRoot: state.stateRoot,
                verifier: contracts.txAdapter,
                stateValidationProof: stateProof,
            });
            signer = created.signer;
            expect(signer).toBe(predicted);
            expect(await chain.publicClient.getCode({ address: signer })).toBeDefined();

            // A second call neither fails nor changes anything.
            const again = await createZKSigner(chain.walletClient, {
                factory: contracts.safeFactory,
                stateRoot: state.stateRoot,
                verifier: contracts.txAdapter,
                stateValidationProof: stateProof,
            });
            expect(again.signer).toBe(signer);
        });

        it("refuses to create a signer for a state root the proof does not commit to", async () => {
            await expect(
                createZKSigner(chain.walletClient, {
                    factory: contracts.safeFactory,
                    stateRoot: state.stateRoot + 1n,
                    verifier: contracts.txAdapter,
                    stateValidationProof: stateProof,
                }),
            ).rejects.toThrow();
        });

        it("exposes its configuration through the proxy", async () => {
            expect(await getZKSignerConfiguration(chain.publicClient, signer)).toEqual({
                stateRoot: state.stateRoot,
                verifier: getAddress(contracts.txAdapter),
            });
        });

        it(
            "validates the SDK's proof as an ERC-1271 signature, via the factory and directly",
            async () => {
                const signatures = await Promise.all([1, 2].map((i) => accounts[i].sign({ hash })));
                proof = (
                    await generateMultiSigProof(config, hash, signatures, state.stateRoot, txCircuit, {
                        barretenberg: api,
                    })
                ).proof;

                expect(
                    await isValidZKSignature(chain.publicClient, {
                        factory: contracts.safeFactory,
                        hash,
                        proof,
                        stateRoot: state.stateRoot,
                        verifier: contracts.txAdapter,
                    }),
                ).toBe(true);

                // What Safe's checkNSignatures does for a contract signature: call isValidSignature(hash, proofData) on the owner.
                const magic = await chain.publicClient.readContract({
                    address: signer,
                    abi: zkMultiSigEcdsaSignerAbi,
                    functionName: "isValidSignature",
                    args: [hash, proof],
                });
                expect(magic).toBe(ERC1271_MAGIC_VALUE);
            },
            TIMEOUT,
        );

        it("rejects the proof for another hash, another state root and a corrupted proof", async () => {
            const check = (h: Hex, p: Hex, root = state.stateRoot) =>
                isValidZKSignature(chain.publicClient, {
                    factory: contracts.safeFactory,
                    hash: h,
                    proof: p,
                    stateRoot: root,
                    verifier: contracts.txAdapter,
                });
            expect(await check(toHex("different", { size: 32 }), proof)).toBe(false);
            expect(await check(hash, proof, state.stateRoot + 1n)).toBe(false);
            const flipped = proof.slice(100, 101) === "a" ? "b" : "a";
            expect(await check(hash, `0x${proof.slice(2, 100)}${flipped}${proof.slice(101)}`)).toBe(false);
        });

        it("the Safe signature blob carries the proof where Safe will read it", () => {
            const blob = encodeZKSignerSignature(signer, proof);
            // static slot: owner (32) | offset (32) | v = 0 (1); then dynamic: length (32) | proof
            expect(blob.slice(2, 66)).toBe(`${"00".repeat(12)}${signer.slice(2).toLowerCase()}`);
            expect(BigInt(`0x${blob.slice(66, 130)}`)).toBe(65n);
            expect(blob.slice(130, 132)).toBe("00");
            expect(BigInt(`0x${blob.slice(132, 196)}`)).toBe(BigInt((proof.length - 2) / 2));
            expect(`0x${blob.slice(196)}`).toBe(proof);
            expect(encodeSafeSignatures([{ signer, data: proof, kind: "contract" }])).toBe(blob);
        });
    });

    describe("Nexus: ZK validator", () => {
        // A stand-in account: an address the validator sees as msg.sender. It first behaves as an EOA (so it
        // can send the transactions a Nexus account would send to its validator), then gets minimal code
        // that answers every read with `true`, enough for the SDK's isModuleInstalled / entryPoint reads.
        const account: Address = "0x00000000000000000000000000000000000a11ce";
        const send = (data: Hex, to: Address) =>
            chain.testClient.sendUnsignedTransaction({ from: account, to, data, gas: 20_000_000n });

        beforeAll(async () => {
            await chain.testClient.setBalance({ address: account, value: 10n ** 20n });
            await chain.testClient.impersonateAccount({ address: account });
        });

        it("installs with the state-validation proof and exposes the state", async () => {
            // installModule forwards this to onInstall(bytes); the account itself is the caller.
            const onInstall = encodeFunctionData({
                abi: zkMultiSigValidatorAbi,
                functionName: "onInstall",
                args: [encodeValidatorInitData(state.stateRoot, stateProof)],
            });
            const hash = await send(onInstall, contracts.validator);
            expect((await chain.publicClient.waitForTransactionReceipt({ hash })).status).toBe("success");

            await chain.testClient.setCode({ address: account, bytecode: "0x600160005260206000f3" });
            const status = await getNexusAccountStatus(chain.publicClient, { account, validator: contracts.validator });
            expect(status).toMatchObject({ installed: true, initialized: true, stateRoot: state.stateRoot });
            expect(await getValidatorStateRoot(chain.publicClient, { account, validator: contracts.validator })).toBe(
                state.stateRoot,
            );
        });

        it(
            "validates a UserOperation whose signature is the SDK's proof, and reports its gas",
            async () => {
                const { userOperation, userOperationHash } = await prepareNexusUserOperation(chain.publicClient, {
                    account,
                    validator: contracts.validator,
                    call: { to: contracts.safeFactory, value: 0n, data: "0x" },
                    nonce: 0n,
                    maxFeePerGas: 1_000_000_000n,
                    maxPriorityFeePerGas: 1_000_000n,
                });
                const signatures = await Promise.all([0, 1].map((i) => accounts[i].sign({ hash: userOperationHash })));
                const signed = await generateNexusUserOperationProof(chain.publicClient, {
                    userOperation,
                    validator: contracts.validator,
                    signatures,
                    config,
                    circuit: txCircuit,
                    options: { barretenberg: api },
                });
                expect(signed.userOperationHash).toBe(userOperationHash);

                const validate = (op: typeof signed.userOperation, hash: Hex) =>
                    chain.publicClient.simulateContract({
                        address: contracts.validator,
                        abi: zkMultiSigValidatorAbi,
                        functionName: "validateUserOp",
                        args: [toPackedUserOperation(op) as never, hash],
                        account,
                    });

                // 0 = VALIDATION_SUCCESS
                expect((await validate(signed.userOperation, userOperationHash)).result).toBe(0n);

                // 1 = VALIDATION_FAILED: another operation hash, or a tampered operation (the hash then changes).
                expect((await validate(signed.userOperation, toHex("other", { size: 32 }))).result).toBe(1n);
                const tampered = { ...signed.userOperation, nonce: 1n };
                expect(
                    (
                        await validate(
                            tampered,
                            getNexusUserOperationHash(tampered, await chain.publicClient.getChainId()),
                        )
                    ).result,
                ).toBe(1n);

                // eth_estimateGas cannot be used here: the adapter swallows an out-of-gas verifier, so the call "succeeds"
                // (returning VALIDATION_FAILED) at any gas. Search for the least gas that still validates instead.
                const validates = async (gas: bigint) =>
                    (
                        await chain.publicClient
                            .simulateContract({
                                address: contracts.validator,
                                abi: zkMultiSigValidatorAbi,
                                functionName: "validateUserOp",
                                args: [toPackedUserOperation(signed.userOperation) as never, userOperationHash],
                                account,
                                gas,
                            })
                            .catch(() => ({ result: 1n }))
                    ).result === 0n;
                let low = 100_000n;
                let high: bigint = DEFAULT_GAS.verificationGasLimit;
                expect(await validates(high)).toBe(true);
                while (high - low > 20_000n) {
                    const mid = (low + high) / 2n;
                    if (await validates(mid)) high = mid;
                    else low = mid;
                }
                console.log(`validateUserOp needs about ${high} gas with a ZK proof`);
                // The default verification limit must leave real headroom over what verification needs.
                expect(high).toBeLessThan(DEFAULT_GAS.verificationGasLimit);
            },
            TIMEOUT,
        );

        it(
            "updates the state root with a new state-validation proof, executed by the account",
            async () => {
                const rotated: MultiSigConfig = { signers: config.signers, threshold: 3, salt: SALT + 1n };
                const rotatedState = createMultiSigState(rotated);
                const newProof = await generateStateValidationProof(rotated, stateCircuit, { barretenberg: api });

                const call = encodeUpdateStateRootCall({
                    validator: contracts.validator,
                    newStateRoot: rotatedState.stateRoot,
                    stateValidationProof: newProof.proof,
                });
                // The account must be an EOA-like sender again for this transaction in the harness.
                await chain.testClient.setCode({ address: account, bytecode: "0x" });
                const hash = await send(call.data, call.to);
                expect((await chain.publicClient.waitForTransactionReceipt({ hash })).status).toBe("success");
                await chain.testClient.setCode({ address: account, bytecode: "0x600160005260206000f3" });

                expect(
                    await getValidatorStateRoot(chain.publicClient, { account, validator: contracts.validator }),
                ).toBe(rotatedState.stateRoot);
            },
            TIMEOUT,
        );

        it("the contract ABI conforms to the SDK's", () => {
            const fixture = loadContract("ZKMultiSigValidator").abi as unknown as { type: string; name?: string }[];
            const names = new Set(fixture.filter((x) => x.type === "function").map((x) => x.name));
            for (const item of zkMultiSigValidatorAbi.filter((x) => x.type === "function")) {
                expect(names.has(item.name), `validator has ${item.name}`).toBe(true);
            }
        });
    });
});
